'use client'

import { useRef, type ReactNode } from 'react'
import { useGSAP } from '@/lib/hooks/useGSAP'
import { prefersReducedMotion, useReducedMotion } from './useReducedMotion'

export type MagneticHoverProps = {
  children: ReactNode
  className?: string
  strength?: number
  duration?: number
  disabled?: boolean
}

export function MagneticHover({
  children,
  className,
  strength = 0.25,
  duration = 0.35,
  disabled = false,
}: MagneticHoverProps) {
  const root = useRef<HTMLDivElement>(null)
  const reduced = useReducedMotion()

  useGSAP(
    ({ gsap }) => {
      const element = root.current
      if (
        !element ||
        disabled ||
        reduced ||
        prefersReducedMotion() ||
        !window.matchMedia('(pointer: fine)').matches
      ) {
        return
      }

      const xTo = gsap.quickTo(element, 'x', { duration, ease: 'power3.out' })
      const yTo = gsap.quickTo(element, 'y', { duration, ease: 'power3.out' })

      const move = (event: PointerEvent): void => {
        const bounds = element.getBoundingClientRect()
        xTo((event.clientX - (bounds.left + bounds.width / 2)) * strength)
        yTo((event.clientY - (bounds.top + bounds.height / 2)) * strength)
      }

      const reset = (): void => {
        xTo(0)
        yTo(0)
      }

      element.addEventListener('pointermove', move)
      element.addEventListener('pointerleave', reset)
      element.addEventListener('pointercancel', reset)

      return () => {
        element.removeEventListener('pointermove', move)
        element.removeEventListener('pointerleave', reset)
        element.removeEventListener('pointercancel', reset)
      }
    },
    [disabled, duration, reduced, strength],
    root,
  )

  return (
    <div ref={root} className={className}>
      {children}
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'

const QUERY = '(prefers-reduced-motion: reduce)'

export function prefersReducedMotion(): boolean {
  return typeof window !== 'undefined' && window.matchMedia(QUERY).matches
}

export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false)

  useEffect(() => {
    const media = window.matchMedia(QUERY)
    const update = (): void => setReduced(media.matches)

    update()
    media.addEventListener('change', update)
    return () => media.removeEventListener('change', update)
  }, [])

  return reduced
}

'use client'

import gsap from 'gsap'
import { ScrollTrigger } from 'gsap/ScrollTrigger'
import { useEffect, type DependencyList, type RefObject } from 'react'

let registered = false

function ensureGsapPlugins(): void {
  if (typeof window === 'undefined' || registered) return
  gsap.registerPlugin(ScrollTrigger)
  registered = true
}

export type GSAPTools = {
  gsap: typeof gsap
  ScrollTrigger: typeof ScrollTrigger
}

export type GSAPCallback = (tools: GSAPTools) => void | (() => void)

export function useGSAP(
  callback: GSAPCallback,
  deps: DependencyList = [],
  scope?: RefObject<Element | null>,
): void {
  useEffect(() => {
    if (typeof window === 'undefined') return

    ensureGsapPlugins()

    let dispose: void | (() => void)
    const context = gsap.context(() => {
      dispose = callback({ gsap, ScrollTrigger })
    }, scope?.current ?? undefined)

    return () => {
      dispose?.()
      context.revert()
    }

    // Dependencies are deliberately controlled by each animation consumer.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps)
}
